let items = $input.all();
if (items[0].json._skip) return items;

const validCategories = ['pemasukan', 'pengeluaran', 'hutang', 'piutang', 'bayar_hutang', 'terima_piutang', 'unclear'];
const rawText = items[0].json.textContent || items[0].json.transcript || '';

function buildFallback(rawText) {
  let nominal = 0;
  let category = 'unclear';
  let item = rawText.slice(0, 80) || null;

  const nominalMatch = rawText.match(/(\d+)\s*(rb|ribu|jt|juta|k|rb\.?)/i);
  if (nominalMatch) {
    nominal = parseInt(nominalMatch[1], 10);
    const unit = nominalMatch[2].toLowerCase();
    if (unit.startsWith('jt') || unit === 'juta') nominal *= 1000000;
    else if (unit === 'k') nominal *= 1000;
    else nominal *= 1000;
  } else {
    const numMatch = rawText.match(/(\d{3,})/);
    if (numMatch) nominal = parseInt(numMatch[1], 10);
  }

  const lowerText = rawText.toLowerCase();
  if (/\b(jual|terima|dapat|masuk|pemasukan|setoran|omset|pendapatan)\b/i.test(lowerText)) category = 'pemasukan';
  else if (/(udah.*bayar.*utang|sudah.*bayar.*utang|lunasin.*utang|dibayar.*utang)/i.test(lowerText)) category = 'terima_piutang';
  else if (/(si.*(minjam|minjem)|dipinjam|minjam.*sama|ngasih.*pinjam|pinjamin)/i.test(lowerText)) category = 'piutang';
  else if (/(bayar.*(hutang|utang)|lunas|nyicil.*(hutang|utang))/i.test(lowerText)) category = 'bayar_hutang';
  else if (/\b(hutang|ngutang|pinjam.*dari|minjam|minjem)\b/i.test(lowerText)) category = 'hutang';
  else if (/\b(beli|bayar|keluar|pengeluaran|belanja|modal|kasbon|ngambil)\b/i.test(lowerText)) category = 'pengeluaran';
  else if (/\b(piutang)\b/i.test(lowerText)) category = 'piutang';

  return { category, nominal, item, pihak: null, tanggal: null, jatuh_tempo: null, confidence: 'low' };
}

function parseClaudeResponse(json) {
  if (!json || !json.message || !json.message.content) return null;
  const content = json.message.content;
  if (!Array.isArray(content) || content.length === 0) return null;
  const textBlock = content.find(b => b.type === 'text');
  if (!textBlock || !textBlock.text) return null;

  let raw = textBlock.text.trim();
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  if (!jsonMatch) return null;

  const parsed = JSON.parse(jsonMatch[0]);
  if (!parsed.category || parsed.nominal === undefined || parsed.nominal === null) return null;
  if (typeof parsed.nominal !== 'number') parsed.nominal = parseInt(parsed.nominal, 10) || 0;
  if (!validCategories.includes(parsed.category)) {
    parsed.category = 'unclear';
    parsed.confidence = 'low';
  }
  return parsed;
}

let extractedData = parseClaudeResponse(items[0].json);

if (!extractedData) {
  console.log('[Validate JSON] Claude extraction failed or returned invalid JSON, using fallback');
  extractedData = buildFallback(rawText);
}

if (!validCategories.includes(extractedData.category)) extractedData.category = 'unclear';
if (typeof extractedData.nominal !== 'number' || isNaN(extractedData.nominal)) extractedData.nominal = 0;

items[0].json.extractedData = extractedData;
items[0].json.claudeRaw = items[0].json.message ? items[0].json.message.content : null;
return items;

